#include "cpu_budget.hpp"
#include <cstdio>
int main(){if(!fsizes::limitCpu()){printf("cap error=%lu\n",GetLastError());return 1;}JOBOBJECT_CPU_RATE_CONTROL_INFORMATION rate{};if(!QueryInformationJobObject(nullptr,JobObjectCpuRateControlInformation,&rate,sizeof(rate),nullptr)||rate.CpuRate!=200)return 2;FILETIME c,e,k,u;GetProcessTimes(GetCurrentProcess(),&c,&e,&k,&u);auto value=[](FILETIME t){return (uint64_t(t.dwHighDateTime)<<32)|t.dwLowDateTime;};auto before=value(k)+value(u);auto start=GetTickCount64();volatile uint64_t work=0;while(GetTickCount64()-start<5000){for(unsigned i=0;i<10000;i++)work+=i;}auto elapsed=GetTickCount64()-start;GetProcessTimes(GetCurrentProcess(),&c,&e,&k,&u);SYSTEM_INFO si;GetSystemInfo(&si);double percent=double(value(k)+value(u)-before)/10000.0/elapsed/si.dwNumberOfProcessors*100;printf("ConfiguredHardCap=%lu/100 percent; busy-work CPU=%.3f%%; elapsed=%llu ms\n",rate.CpuRate,percent,elapsed);return percent<=2.8?0:3;}
